            archetypeSignatureName: '典藏',
            archetypeSignatureTagline: '罗马数字编号的部、带编号的章、分节符。',
            blurbSubmission: '6×9 页面上的朴素阅读稿，采用无衬线字体、1.5 倍行距和独立的场景开篇页。可为您的读者自定义其版面几何与字体排印。',
            blurbReadingDraft: '面向试读者和校对者的精致阅读稿。足够整洁，看起来像一本成书，又无需确定最终的美学风格。当代衬线正文字体、舒适的间距和克制的结构，与现代商业小说的观感保持一致。',
            blurbLiterary: '精致且具出版水准 — 专业排版的大众平装小说质感。页眉、结构化的章节呈现和更强的视觉节奏营造出更沉浸的阅读体验，同时保持克制且高度易读。',
            blurbStructured: '建筑感与文学性兼具。专为受益于从容节奏、结构留白、幕开篇页、题记和独特场景呈现的雄心之作而打造。令人联想到精品文学版本的匠心与世纪中叶印刷设计传统。',
            notePage: '页面尺寸和页边距对阅读体验的影响远超大多数作者的想象。更紧凑的版面会提高密度并加快节奏，而更宽的页边距则带来视觉留白和更浓的文学气息。大多数大众小说会在易读性与经济的页数之间取得平衡。',
            noteBody: '正文排印决定了长篇阅读的舒适度。衬线字体在印刷小说中仍占主导地位，因为它们能引导视线自然地扫过密集的文字页面。行距会微妙地影响节奏：更紧凑的版面显得更快、更紧迫，而宽松的行距会放慢读者速度、引发思考。',
            noteHeaders: '页眉帮助读者在较长的作品中保持方向感，在正式印刷版本中很常见。草稿手稿通常完全省略页眉，而精致的大众和文学版式常常使用克制的页眉来强化结构，又不分散对正文的注意。',
            noteFolio: '页码悄然地为读者在手稿中定位。传统草稿通常将页码置于页面底部居中，而已出版的小说常将其整合进页眉系统，以获得更精致的呈现。',
            noteParts: '部的扉页划分主要的叙事段落，并在幕或故事阶段之间营造结构留白。文学小说和大体量的商业小说常使用专门的部开篇页、罗马数字或题记，以强化主题转换和长篇的推进力。',
            noteChapters: '章的呈现方式塑造叙事节奏。极简的章页让节奏隐形而迅速，而较大的开篇页则营造停顿、强调和期待。统一的章标题和开篇间距可以微妙地强化基调与类型预期。',
            noteScenes: '场景分隔在微观层面控制推进力。无形的过渡带来速度和连贯性，而专门的场景开篇页则赋予每个段落情感或结构上的分量。编号、标题和装饰线有助于读者在复杂的叙事中找到方向。',
            noteEpigraph: '题记在正文开始前为一个段落设定情感或主题视角。有些小说会节制地使用题记以作强调，而文学性和结构性较强的小说可能使用反复出现的题记，在幕、章或人物弧线之间营造共鸣。',
